          this.context.toast('Could not focus agent composer', messageOf(error))
        }
      } else if (pane) this.handleOf(pane)?.focus()
      return
    }
    await this.run(() => this.context.call('quirky.terminal/activateTab', { tab: tabId }), 'switch tabs')
  }

